// Parse event details from webhook
const body = $input.item.json.body || $input.item.json;

const event = {
  name: body.event_name || 'Evenement Wellness',
  type: body.event_type || 'soiree', // brunch|soiree|retreat|atelier|plein_air|challenge
  date: body.date || new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  time: body.time || '18:00',
  location: body.location || 'Studio Montreal',
  capacity: body.capacity || 30,
  price: body.price || 0, // 0 = inclus dans membership
  description: body.description || '',
  audience: body.audience || 'tous', // membres|tous|premium
  early_bird_deadline: body.early_bird_deadline || null,
  early_bird_price: body.early_bird_price || null
};

return { json: event };

