const event = $('Parse Event Details').item.json;
const aiResponse = $input.item.json.message.content;
let promo;
try { promo = JSON.parse(aiResponse); } catch (e) { promo = { error: 'Parse failed' }; }

// Schedule content in calendar
const eventDate = new Date(event.date);
const posts = [];

// Announcement post (now)
posts.push({
  title: `Annonce: ${event.name}`,
  content_type: 'post',
  platform: 'meta',
  content: promo.instagram_post,
  scheduled_at: new Date().toISOString(),
  status: 'approved'
});

// Countdown J-7
if (promo.countdown_posts?.[0]) {
  const j7 = new Date(eventDate.getTime() - 7 * 24 * 60 * 60 * 1000);
  posts.push({
    title: `${event.name} - J-7`,
    content_type: 'post',
    platform: 'meta',
    content: promo.countdown_posts[0],
    scheduled_at: j7.toISOString(),
    status: 'approved'
  });
}

// Countdown J-3
if (promo.countdown_posts?.[1]) {
  const j3 = new Date(eventDate.getTime() - 3 * 24 * 60 * 60 * 1000);
  posts.push({
    title: `${event.name} - J-3`,
    content_type: 'post',
    platform: 'meta',
    content: promo.countdown_posts[1],
    scheduled_at: j3.toISOString(),
    status: 'approved'
  });
}

// Countdown J-1
if (promo.countdown_posts?.[2]) {
  const j1 = new Date(eventDate.getTime() - 1 * 24 * 60 * 60 * 1000);
  posts.push({
    title: `${event.name} - Demain!`,
    content_type: 'post',
    platform: 'meta',
    content: promo.countdown_posts[2],
    scheduled_at: j1.toISOString(),
    status: 'approved'
  });
}

// TikTok teaser
posts.push({
  title: `TikTok: ${event.name}`,
  content_type: 'reel',
  platform: 'tiktok',
  content: promo.tiktok_script,
  scheduled_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
  status: 'draft'
});

return {
  json: {
    event,
    promo,
    scheduled_posts: posts,
    posts_count: posts.length
  }
};
